basicCode.vanilla:
import { createApprovalCard } from '@/components/ui/approval-card';

createApprovalCard({
  question: 'Permitir que o agente publique o relatório?',
  scope: [
    { term: 'Ferramenta', detail: 'publicar_relatorio' },
    { term: 'Alvo', detail: 'docs/shared/relatorios/' },
  ],
  actions: [allowOnce, deny],
  onChoose: (choice) => answer(choice),
});

basicCode.react:
import { ApprovalCard } from "@/components/ui/approval-card";

<ApprovalCard
  question="Permitir que o agente publique o relatório?"
  scope={scope}
  actions={[allowOnce, deny]}
  onChoose={(choice) => answer(choice)}
/>

extensibilityCode.web:
// O evento relata o VALOR do controle acionado, e nada mais.
onChoose('allow-once');
onChoose('always');
onChoose('deny');

// Controle que não se declara resposta não dispara nada: um link de
// "saiba mais" no meio dos controles continua sendo só um link.

customizationCode.web:
/* A largura é de quem consome: o cartão cresce até onde a conversa der. */
.nds-approval-card {
  max-inline-size: 32rem;
}

/* Empilhar os controles é escolha de quem consome, e ela não muda a ordem — que é a mesma da leitura e a mesma do foco. */
.nds-approval-card-actions {
  flex-direction: column;
  align-items: stretch;
}

